def choose_move(observation):
    x, y = observation['self_position']
    ox, oy = observation['opponent_position']
    obstacles = set(observation['obstacles'])
    resources = observation['resources']
    width, height = observation['grid_width'], observation['grid_height']
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    moves = {'up': (0,-1), 'down': (0,1), 'left': (-1,0), 'right': (1,0)}
    # Decide target zone or resource
    target = None
    if resources:
        targets = resources
        target = min(targets, key=lambda r: dist((x,y), r))
    else:
        # Move toward opponent
        target = (ox, oy)
    dx = dy = 0
    if target:
        if target[0] > x: dx = 1
        elif target[0] < x: dx = -1
        if target[1] > y: dy = 1
        elif target[1] < y: dy = -1
    # Prioritize horizontal or vertical based on distance
    if abs(target[0] - x) >= abs(target[1] - y):
        dy = 0
    else:
        dx = 0
    # Check for obstacles and boundaries
    nx, ny = x + dx, y + dy
    if (nx, ny) in obstacles or nx < 0 or ny < 0 or nx >= width or ny >= height:
        for mdx, mdy in moves.values():
            nx2, ny2 = x + mdx, y + mdy
            if 0 <= nx2 < width and 0 <= ny2 < height and (nx2, ny2) not in obstacles:
                return [mdx, mdy]
        return [0, 0]
    return [dx, dy]
